package java.util.function;
public interface DoublePredicate { boolean test(double value); default DoublePredicate and(final DoublePredicate p){java.util.Objects.requireNonNull(p);return new DoublePredicate(){public boolean test(double v){return DoublePredicate.this.test(v)&&p.test(v);}};} default DoublePredicate or(final DoublePredicate p){java.util.Objects.requireNonNull(p);return new DoublePredicate(){public boolean test(double v){return DoublePredicate.this.test(v)||p.test(v);}};} default DoublePredicate negate(){return new DoublePredicate(){public boolean test(double v){return !DoublePredicate.this.test(v);}};} }
